snippet_css:
:root{
  --bg: #FFF8F6;
  --fg: #8A3B53;
  --muted: #7A5561;
  --surface: #FDEEF2;
  --border: #F0D3DA;
  --accent: #A8405F;
  --accent-fg: #FFF8F6;
  --accent-grad: linear-gradient(180deg,#B0516B,#A8405F);
  --radius: 20px;
  --radius-sm: 12px;
  --shadow: 0 10px 24px rgba(196,106,133,.20);
  --btn-shadow: 0 4px 0 rgba(168,64,95,.22);
  --art-bg: radial-gradient(circle at 50% 45%,#fff 0 14%,transparent 15%),linear-gradient(#F8D7DF,#EFA7B8);
  --media-bg: radial-gradient(circle at 40% 40%,#fff 0 30%,#EDE4DC 60%,transparent 62%);
  --cta-bg: linear-gradient(180deg,#FDEEF2,#F8D7DF);
  --input-bg: #FFFFFF;
  --ok: #2E6E4E;
  --warn: #B03A54;
  --ribbon: #EFA7B8;
  --pearl: #EDE4DC;
  --font-script: 'Pinyon Script',cursive;
  --font-display: 'Bodoni Moda','Noto Serif TC',serif;
  --font-body: 'Cormorant','Noto Serif TC',serif;
  --font-mono: 'Cormorant',ui-serif,serif;
  --focus-ring: var(--accent);
}

